// Originally generated by scripts/port-map.py from the standalone map, then hand-edited. Edit the data in
// data/erd.v5.json; edit behaviour here. Plain JS on purpose: this is the vanilla map engine, mounted by
// components/ErdMap.tsx. Motion (viewport tweens, node intro, selection pulse) uses anime.js and is skipped
// when the OS asks for reduced motion.
import { animate, engine } from "animejs";
engine.pauseOnDocumentHidden = false; // viewport tweens must finish even if the tab is briefly hidden

const I = (d, cls) => `<svg${cls ? ` class="${cls}"` : ""} viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${d}</svg>`;
const IC = {
  search: I('<circle cx="11" cy="11" r="8"/><path d="m21 21-4.3-4.3"/>'),
  chev: I('<path d="m6 9 6 6 6-6"/>'),
  fit: I('<path d="M8 3H5a2 2 0 0 0-2 2v3"/><path d="M21 8V5a2 2 0 0 0-2-2h-3"/><path d="M3 16v3a2 2 0 0 0 2 2h3"/><path d="M16 21h3a2 2 0 0 0 2-2v-3"/>'),
  plus: I('<path d="M5 12h14"/><path d="M12 5v14"/>'),
  minus: I('<path d="M5 12h14"/>'),
  info: I('<circle cx="12" cy="12" r="10"/><path d="M12 16v-4"/><path d="M12 8h.01"/>'),
  click: I('<path d="M14 4.1 12 6"/><path d="m5.1 8-2.9-.8"/><path d="m6 12-1.9 2"/><path d="M7.2 2.2 8 5.1"/><path d="M9.037 9.69a.498.498 0 0 1 .653-.653l11 4.5a.5.5 0 0 1-.074.949l-4.349 1.041a1 1 0 0 0-.74.739l-1.04 4.35a.5.5 0 0 1-.95.074z"/>'),
  branch: I('<line x1="6" x2="6" y1="3" y2="15"/><circle cx="18" cy="6" r="3"/><circle cx="6" cy="18" r="3"/><path d="M18 9a9 9 0 0 1-9 9"/>'),
  route: I('<circle cx="6" cy="19" r="3"/><path d="M9 19h8.5a3.5 3.5 0 0 0 0-7h-11a3.5 3.5 0 0 1 0-7H15"/><circle cx="18" cy="5" r="3"/>'),
  chat: I('<path d="M7.9 20A9 9 0 1 0 4 16.1L2 22Z"/>'),
  hide: I('<rect width="18" height="18" x="3" y="3" rx="2"/><path d="M15 3v18"/><path d="m8 9 3 3-3 3"/>'),
  show: I('<rect width="18" height="18" x="3" y="3" rx="2"/><path d="M15 3v18"/><path d="m10 15-3-3 3-3"/>'),
  left: I('<path d="m12 19-7-7 7-7"/><path d="M19 12H5"/>'),
  right: I('<path d="M5 12h14"/><path d="m12 5 7 7-7 7"/>'),
  x: I('<path d="M18 6 6 18"/><path d="m6 6 12 12"/>'),
  eye: I('<path d="M2.062 12.348a1 1 0 0 1 0-.696 10.75 10.75 0 0 1 19.876 0 1 1 0 0 1 0 .696 10.75 10.75 0 0 1-19.876 0"/><circle cx="12" cy="12" r="3"/>'),
};

