function setTab(t){pHead.querySelectorAll('.ptab').forEach(b=>b.classList.toggle('on',b.dataset.tab===t));pBody.hidden=t!=='details';chatEl.hidden=t!=='ask';oqEl.hidden=t!=='oq';if(t!=='details')setPanel(true);moveInk();if(t==='ask')setTimeout(()=>chatIn.focus(),50);cfg.onEvent&&cfg.onEvent('tab',{tab:t})}
